"use client"

import * as React from "react"

import "./motion-state-swap.css"

export type MotionStateSwapProps = {
  firstLabel?: string
  secondLabel?: string
  className?: string
}

export function MotionStateSwap({ firstLabel = "Ready to review", secondLabel = "Review complete", className }: MotionStateSwapProps) {
  const [complete, setComplete] = React.useState(false)

  return (
    <div className={["kit-motion-swap", className].filter(Boolean).join(" ")} data-state={complete ? "complete" : "ready"}>
      <div className="kit-motion-swap__status" aria-hidden="true">
        <span data-label="ready">{firstLabel}</span>
        <span data-label="complete">{secondLabel}</span>
      </div>
      <span className="kit-motion-swap__announcement" aria-live="polite">{complete ? secondLabel : firstLabel}</span>
      <button type="button" onClick={() => setComplete((value) => !value)}>{complete ? "Return to review" : "Complete review"}</button>
    </div>
  )
}

.kit-motion-swap {
  display: grid;
  justify-items: start;
  gap: 14px;
  color: var(--foreground);
  font-family: var(--font-sans, ui-sans-serif, system-ui, sans-serif);
}

.kit-motion-swap__status {
  display: inline-grid;
  min-height: 28px;
  align-items: center;
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -0.025em;
}

.kit-motion-swap__status span {
  grid-area: 1 / 1;
  opacity: 0;
  transform: translateY(var(--kit-motion-distance-small, 4px));
  transition: opacity var(--kit-motion-duration, 180ms) var(--kit-motion-ease, cubic-bezier(0.23, 1, 0.32, 1)), transform var(--kit-motion-duration, 180ms) var(--kit-motion-ease, cubic-bezier(0.23, 1, 0.32, 1));
}

.kit-motion-swap[data-state="ready"] [data-label="ready"],
.kit-motion-swap[data-state="complete"] [data-label="complete"] {
  opacity: 1;
  transform: translateY(0);
}

.kit-motion-swap[data-state="complete"] [data-label="ready"],
.kit-motion-swap[data-state="ready"] [data-label="complete"] {
  transform: translateY(calc(var(--kit-motion-distance-small, 4px) * -1));
}

.kit-motion-swap[data-state="complete"] [data-label="complete"] {
  color: var(--positive, var(--primary));
}

.kit-motion-swap__announcement {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.kit-motion-swap button {
  min-height: 44px;
  padding-inline: 16px;
  border: 1px solid var(--primary);
  border-radius: var(--radius-control, 10px);
  background: var(--primary);
  color: var(--primary-foreground);
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  box-shadow: var(--shadow-control, 0 1px 2px oklch(0 0 0 / 0.12));
  transition: transform var(--kit-motion-fast, 120ms) var(--kit-motion-ease, cubic-bezier(0.23, 1, 0.32, 1));
}

.kit-motion-swap button:active {
  transform: translateY(1px);
}

.kit-motion-swap button:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

.kit-motion-reduced .kit-motion-swap[data-state] .kit-motion-swap__status span {
  transform: none;
  transition: opacity 120ms linear;
}

@media (prefers-reduced-motion: reduce) {
  .kit-motion-swap[data-state] .kit-motion-swap__status span {
    transform: none;
    transition: opacity 120ms linear;
  }

  .kit-motion-swap button {
    transition: none;
  }

  .kit-motion-swap button:active {
    transform: none;
  }
}
